#include "store.h"
#include <streambuf>
#include <mutex>

// options:  --plain = no colors     --color = force colors
//==========================================================================
// CLEAR SCREEN
// Clears the terminal so the old menus don't stay on screen.
//
// Simple idea:
//   1. The user answers a menu ("Choice: ")  ->  clear the screen, then show the result.
//   2. The program asks for more info ("Username: ")  ->  don't clear, the user still needs it.
//==========================================================================

// clears the terminal
// --clear: some consoles (for example the CLion Run window) are not real terminals and ignore the clear codes.
// With this flag the screen is also pushed away with blank lines, so only the new content stays in view.
static bool g_floodBlankLines = false;

//--- wipeConsole ----------------------------------------------------------------------------------
// What    : Clears the screen and the scrollback (ANSI codes, or the Windows console API). With
//           --clear it also prints blank lines, for consoles that ignore the clear codes.
// Used by : ScreenBuf::clearNow, ScreenBuf::write
//--------------------------------------------------------------------------------------------------
void wipeConsole(std::streambuf* dest) {
    dest->pubsync();
#ifdef _WIN32
    HANDLE hStdOut = GetStdHandle(STD_OUTPUT_HANDLE);
    CONSOLE_SCREEN_BUFFER_INFO csbi;
    if (hStdOut != INVALID_HANDLE_VALUE && GetConsoleScreenBufferInfo(hStdOut, &csbi)) {
        DWORD count;
        DWORD cellCount = (DWORD)csbi.dwSize.X * (DWORD)csbi.dwSize.Y;
        COORD homeCoords = {0, 0};
        FillConsoleOutputCharacterA(hStdOut, ' ', cellCount, homeCoords, &count);
        FillConsoleOutputAttribute(hStdOut, csbi.wAttributes, cellCount, homeCoords, &count);
        SetConsoleCursorPosition(hStdOut, homeCoords);
    }
#endif
    const char codes[] = "\033[2J\033[3J\033[H";
    dest->sputn(codes, (std::streamsize)(sizeof(codes) - 1));
    if (g_floodBlankLines) {
        const std::string blanks(80, '\n');
        dest->sputn(blanks.data(), (std::streamsize)blanks.size());
    }
    dest->pubsync();
}

// prompts after which the user is looking at a NEW screen
//--- isScreenChangingPrompt -----------------------------------------------------------------------
// What    : Tells if a prompt belongs to a screen that should be cleared when the user answers it
//           ("Choice: ", "Search (", ...).
// Returns : true for those prompts
// Used by : ScreenBuf::userPressedEnter
//--------------------------------------------------------------------------------------------------
bool isScreenChangingPrompt(const std::string& p) {
    const char* starts[] = {"Choice: ", "Game id or title: ", "Search (", "Amount to add", "Chat with (", "Sort by: "};
    for (size_t i = 0; i < sizeof(starts) / sizeof(starts[0]); i++) {
        if (p.compare(0, std::string(starts[i]).size(), starts[i]) == 0) return true;
    }
    return false;
}

// filter on std::cout
class ScreenBuf : public std::streambuf {
private:
    std::streambuf* dest;
    std::mutex lock;               // the chat thread prints too
    std::string line;              // the unfinished line printed so far (a prompt, while the program waits)
    std::string prompt;            // the last prompt that was flushed
    bool pendingClear = false;     // the user moved on, clear before the next real output
    std::string held;              // output that is waiting while pendingClear is true

//--- ScreenBuf::releaseHeld -----------------------------------------------------------------------
// What    : Sends the output that was held back to the real console.
// Used by : ScreenBuf::finish, ScreenBuf::sync, ScreenBuf::write
//--------------------------------------------------------------------------------------------------
    void releaseHeld() {
        if (!held.empty()) dest->sputn(held.data(), (std::streamsize)held.size());
        held.clear();
    }

//--- ScreenBuf::write -----------------------------------------------------------------------------
// What    : Common writer of overflow and xsputn. It keeps track of the unfinished line (the
//           prompt). When a clear is pending it holds the output until a full line arrives, then
//           clears the screen and releases it.
// Used by : ScreenBuf::overflow, ScreenBuf::xsputn
//--------------------------------------------------------------------------------------------------
    void write(const char* s, std::streamsize n) {
        for (std::streamsize i = 0; i < n; i++) {
            if (s[i] == '\n') line.clear();
            else line.push_back(s[i]);
        }
        if (!pendingClear) { dest->sputn(s, n); return; }

        held.append(s, (size_t)n);
        if (held.find('\n') != std::string::npos) {     // a result or a new screen is coming: clear first
            pendingClear = false;
            wipeConsole(dest);
            releaseHeld();
        }
    }
public:
//--- ScreenBuf::ScreenBuf -------------------------------------------------------------------------
// What    : Wraps the output stream buffer that receives the text.
// Used by : main
//--------------------------------------------------------------------------------------------------
    explicit ScreenBuf(std::streambuf* target) : dest(target) {}
    // called by LineBuf when the user pressed Enter
//--- ScreenBuf::userPressedEnter ------------------------------------------------------------------
// What    : Called by LineBuf when the user pressed Enter. If the last prompt was a screen-changing
//           one, the next output starts on a cleared screen.
// Used by : LineBuf::underflow
//--------------------------------------------------------------------------------------------------
    void userPressedEnter() {
        std::lock_guard<std::mutex> guard(lock);
        bool changed = isScreenChangingPrompt(prompt);
        prompt.clear();
        line.clear();
        if (changed) pendingClear = true;
    }
    // clear right now (used once at the start)
//--- ScreenBuf::clearNow --------------------------------------------------------------------------
// What    : Clears the console right away (done once at the start).
// Used by : main
//--------------------------------------------------------------------------------------------------
    void clearNow() {
        std::lock_guard<std::mutex> guard(lock);
        wipeConsole(dest);
    }
    // give back anything that is still waiting
//--- ScreenBuf::finish ----------------------------------------------------------------------------
// What    : Cancels a pending clear and prints whatever is still held, at the end of the program.
// Used by : main
//--------------------------------------------------------------------------------------------------
    void finish() {
        std::lock_guard<std::mutex> guard(lock);
        pendingClear = false;
        releaseHeld();
        dest->pubsync();
    }

protected:
//--- ScreenBuf::overflow --------------------------------------------------------------------------
// What    : std::streambuf hook for one character.
// Returns : the character, or EOF on error
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int_type overflow(int_type ch) override {
        if (traits_type::eq_int_type(ch, traits_type::eof())) return traits_type::not_eof(ch);
        char c = traits_type::to_char_type(ch);
        std::lock_guard<std::mutex> guard(lock);
        write(&c, 1);
        return ch;
    }

//--- ScreenBuf::xsputn ----------------------------------------------------------------------------
// What    : std::streambuf hook for a block of characters.
// Returns : how many characters were taken
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    std::streamsize xsputn(const char* s, std::streamsize n) override {
        std::lock_guard<std::mutex> guard(lock);
        write(s, n);
        return n;
    }

//--- ScreenBuf::sync ------------------------------------------------------------------------------
// What    : Flush hook. A flush with an unfinished line is a prompt, so a pending clear is
//           cancelled (the user still needs the old screen to answer) and the prompt text is
//           remembered.
// Returns : 0 on success
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int sync() override {
        std::lock_guard<std::mutex> guard(lock);
        // a flush with unfinished text and nothing else is a prompt (the program waits for the user).
        // the user still needs the old screen to answer it, so cancel the clear.
        if (pendingClear && !held.empty() && held.find('\n') == std::string::npos) {
            pendingClear = false;
            releaseHeld();
        }
        if (!line.empty()) prompt = line;
        return dest->pubsync();
    }
};

// filter on std::cin: hands over one line at a time and tells ScreenBuf when a line was entered
class LineBuf : public std::streambuf {
private:
    std::streambuf* src;
    ScreenBuf* screen;
    std::string buffer;

public:
//--- LineBuf::LineBuf -----------------------------------------------------------------------------
// What    : Wraps the input stream buffer and the ScreenBuf.
// Used by : main
//--------------------------------------------------------------------------------------------------
    LineBuf(std::streambuf* source, ScreenBuf* out) : src(source), screen(out) {}

protected:
//--- LineBuf::underflow ---------------------------------------------------------------------------
// What    : std::streambuf hook for input: reads one whole line from the real input, tells the
//           ScreenBuf that Enter was pressed, and hands the line over.
// Returns : the next character, or EOF at the end of the input
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    int_type underflow() override {
        if (gptr() < egptr()) return traits_type::to_int_type(*gptr());

        buffer.clear();
        int_type c;
        while (!traits_type::eq_int_type(c = src->sbumpc(), traits_type::eof())) {
            buffer.push_back(traits_type::to_char_type(c));
            if (buffer.back() == '\n') break;
        }
        if (buffer.empty()) return traits_type::eof();

        screen->userPressedEnter();
        setg(&buffer[0], &buffer[0], &buffer[0] + buffer.size());
        return traits_type::to_int_type(*gptr());
    }
};

//--- isRealTerminal -------------------------------------------------------------------------------
// What    : Tells if the output is a real terminal (not a pipe or a file).
// Returns : true for a terminal
// Used by : main
//--------------------------------------------------------------------------------------------------
bool isRealTerminal() {
#ifdef _WIN32
    return _isatty(_fileno(stdin)) && _isatty(_fileno(stdout));
#else
    return isatty(STDIN_FILENO) && isatty(STDOUT_FILENO);
#endif
}

//--- main -----------------------------------------------------------------------------------------
// What    : Program entry. Reads --plain and --color, sets the color mode, and runs the store. In a
//           real terminal the screen-clearing filters are installed around runStore; with piped
//           input or output nothing is cleared.
// Returns : 0
// Used by : the operating system (program entry point)
//--------------------------------------------------------------------------------------------------
int main(int argc, char* argv[]) {
    bool allowColor = true;
    bool forceColor = false;
    bool forceClear = false;
    bool showcase = false;
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg == "--plain") allowColor = false;
        if (arg == "--color") forceColor = true;
        if (arg == "--clear") forceClear = true;
        if (arg == "--showcase") showcase = true;
    }
    g_floodBlankLines = forceClear;
    tuiInit(allowColor, forceColor);

    if (!isRealTerminal() && !forceClear) {
        runStore(showcase);                         // output to a file or piped input: no clearing
        return 0;
    }

    std::streambuf* originalOut = std::cout.rdbuf();
    std::streambuf* originalIn = std::cin.rdbuf();
    ScreenBuf screen(originalOut);
    LineBuf input(originalIn, &screen);
    std::cout.rdbuf(&screen);
    std::cin.rdbuf(&input);

    screen.clearNow();
    runStore(showcase);

    screen.finish();
    std::cout.rdbuf(originalOut);
    std::cin.rdbuf(originalIn);
    return 0;
}
